test('all roles reference existing modules and render their full menus',()=>{for(const r of Object.keys(roles)){role=r;for(const k of allowedPages()){assert.ok(modules[k],r+':'+k);current=k;const html=pageContent();assert.equal(typeof html,'string');assert.ok(html.length>30,r+':'+k)}renderSidebar();renderMobile();assert.ok(document.querySelector('#sidebar-nav').innerHTML.includes('الرئيسية'))}});
test('mobile shortcuts use real icon keys and allowed pages',()=>{for(const r of Object.keys(roles)){role=r;for(const feature of mobileFeatures[r])assert.ok(paths[feature[3]],r+':'+feature[1]);const html=mobileFeatureGrid();for(const match of html.matchAll(/data-page="([^"]+)"/g))assert.ok(allowedPages().includes(match[1]),r+':'+match[1])}});
test('navigation rejects cross-role shortcuts and unauthenticated navigation',()=>{role='student';current='owner';navigate('ledger');assert.equal(current,'owner');authenticated=false;navigate('courses');assert.equal(current,'owner');authenticated=true});
test('every table schema matches the actual data cell count',()=>{for(const [key,s] of Object.entries(tableSchemas)){for(const row of s.rows){const expected=s.columns.at(-1)===''?s.columns.length-1:s.columns.length;assert.equal(row.length,expected,key)}}});
test('every table has exactly one cell per header',()=>{for(const [key,s] of Object.entries(tableSchemas)){const html=rowHTML(s.rows[0],0,s.columns);assert.equal((html.match(/<td>/g)||[]).length,s.columns.length,key)}});
test('October has 31 days, weekday offset and accurate sample totals',()=>{attendanceYear=2026;attendanceMonth=9;const html=mobileAttendanceCalendar();assert.equal((html.match(/data-day=/g)||[]).length,31);assert.equal((html.match(/<span aria-hidden="true"><\/span>/g)||[]).length,4);assert.equal(Object.values(attendanceStates).filter(s=>s==='absent').length,3)});
test('calendar supports leap February without inventing records',()=>{attendanceYear=2028;attendanceMonth=1;const html=mobileAttendanceCalendar();assert.equal((html.match(/data-day=/g)||[]).length,29);assert.ok(html.includes('لا توجد سجلات معاينة لهذا الشهر'))});
test('CSV quoting handles commas, quotes, linebreaks and spreadsheet formulas',()=>{assert.equal(csvCell('a,b'),'"a,b"');assert.equal(csvCell('a"b'),'"a""b"');assert.equal(csvCell('=1+2'),'"\'=1+2"');assert.equal(csvCell('x\ny'),'"x\ny"')});
